do
  local bad, first = 0, nil
  for i, v in ipairs(V) do
    local a = S.calc_angle(v[1], v[2], v[3], v[4])
    local xa, ya = S.calc_distance(a, 32)
    local xs, ys = S.calc_distance_hp(a, 32)
    local pts = S.shell_points(v[1], v[2], a, 8.5)
    local ok = a == v[5] and xa == v[6] and ya == v[7] and xs == v[8] and ys == v[9]
    local k = 1
    for t = 1, 64 do
      if t == 1 or t % 8 == 0 then
        if pts[2 * t - 1] ~= v[10][k] or pts[2 * t] ~= v[10][k + 1] then ok = false end
        k = k + 2
      end
    end
    if not ok then bad = bad + 1; first = first or i end
  end
  check(string.format("%d engine vectors: angle, steps, points equal", #V), bad == 0,
        string.format("%d bad, first #%s", bad, tostring(first)))
  check("pill shell lives 64 ticks", S.life_ticks(8.5) == 64, S.life_ticks(8.5))
  check("tank shell lives 52 ticks", S.life_ticks(7) == 52, S.life_ticks(7))
end

-- A small world: a table of terrain and a table of pills by square.
local T = { BUILDING = 0, FOREST = 5, GRASS = 7, HALFBUILD = 8, BOAT = 9 }
local function make_env(terrain, pills)
  return {
    ttype = function(mx, my) return terrain[my * 256 + mx] or T.GRASS end,
    pill_on = function(mx, my) return pills[my * 256 + mx] end,
    is_ally = function(p) return p.owner == "friendly" end,
    cover_of_pill = function(p) return 5 * math.floor((p.health or 0) / 5) end,
    T_BUILDING = T.BUILDING, T_HALFBUILD = T.HALFBUILD, T_BOAT = T.BOAT, T_FOREST = T.FOREST,
    wall_shots = 5, half_wall_shots = 5, boat_shots = 1, forest_transparent = true,
    base_stops = function() return false end,
  }
end
local function c(m) return m * 256 + 128 end
local function sq(mx, my) return my * 256 + mx end

-- Pill at (128,120), tank centre on the square 7 south (128,127).
do
  local env = make_env({}, {})
  local r = S.cast(env, c(128), c(120), c(128), c(127), 8.5)
  check("open ground: shell hits the tank", r.hit == "tank", r.hit)
  check("open ground: no cover", r.cover == 0, r.cover)
  -- first point inside 112 wu: start 160 + 32 t >= 1792 - 112 => t = 48
  check("open ground: hit tick 48 (first point < 112 wu)", r.t == 48, r.t)
end
do
  local env = make_env({ [sq(128, 124)] = T.BUILDING }, {})
  local r = S.cast(env, c(128), c(120), c(128), c(127), 8.5)
  check("one wall: cover 5", r.cover == 5, r.cover)
  check("one wall: blocker kind wall", r.block[1] and r.block[1].kind == "wall", r.block[1] and r.block[1].kind)
end
do
  local env = make_env({ [sq(128, 123)] = T.BUILDING, [sq(128, 124)] = T.HALFBUILD,
                         [sq(128, 125)] = T.FOREST, [sq(128, 122)] = T.BOAT }, {})
  local r = S.cast(env, c(128), c(120), c(128), c(127), 8.5)
  check("wall + half wall + boat add, forest open: cover 11", r.cover == 11, r.cover)
end
do
  local pills = { [sq(128, 123)] = { owner = "friendly", health = 13 } }
  local env = make_env({ [sq(128, 125)] = T.BUILDING }, pills)
  local r = S.cast(env, c(128), c(120), c(128), c(127), 8.5)
  check("allied pill hp 13 = 10 shots + wall 5 = 15", r.cover == 15, r.cover)
  check("no link for an allied pill", r.link == nil, r.link)
end
do
  local B = { owner = "neutral", health = 15 }
  local pills = { [sq(128, 122)] = B }
  local env = make_env({ [sq(128, 125)] = T.BUILDING }, pills)
  local r = S.cast(env, c(128), c(120), c(128), c(127), 8.5)
  check("hostile pill on the ray is a link", r.link == B, r.link)
  check("link: front cover 0, tail cover 5 (wall behind it)", r.front == 0 and r.cover == 5,
        r.front .. "/" .. r.cover)
end
do
  -- planned blockers
  local env = make_env({}, {})
  local r = S.cast(env, c(128), c(120), c(128), c(127), 8.5, { [sq(128, 124)] = 5, [sq(128, 123)] = 15 })
  check("planned wall 5 + dropped pill 15 = 20", r.cover == 20, r.cover)
end
do
  -- out of reach: 2208 wu is the last point; a tank 9 squares (2304 wu)
  -- away is still inside 112 wu of it, 10 squares (2560 wu) is not
  local env = make_env({}, {})
  local r = S.cast(env, c(128), c(120), c(128), c(130), 8.5)
  check("tank 10 squares away: shell dies first", r.hit == "reach", r.hit)
end
do
  -- the circle: tank 100 wu beside the axis is hit, 130 wu is not
  local env = make_env({}, {})
  local r1 = S.cast(env, c(128), c(120), c(128) + 100, c(126), 8.5)
  check("tank off-axis: aimed ray still hits it", r1.hit == "tank", r1.hit)
  -- a ray aimed at another point passes 130 wu to the side of our tank:
  -- emulate by casting at the far point and testing distance by hand
  local pts = S.shell_points(c(128), c(120), S.calc_angle(c(128), c(120), c(128), c(127)), 8.5)
  local mind = 1e9
  for t = 1, 64 do
    local dx, dy = pts[2 * t - 1] - (c(128) + 130), pts[2 * t] - c(126)
    mind = math.min(mind, math.sqrt(dx * dx + dy * dy))
  end
  check("a straight ray passes 130 wu from a side tank (> 112, a miss)", mind >= 112, mind)
end
do
  -- the tank's shot: blocked by a wall, a pill, a planned wall; short
  local env = make_env({ [sq(128, 124)] = T.BUILDING }, {})
  local ok, why = S.tank_shot(env, c(128), c(127), c(128), c(120), 128, 120)
  check("tank shot through a wall: blocked", not ok and why == "wall", why)
  env = make_env({}, {})
  ok, why = S.tank_shot(env, c(128), c(127), c(128), c(120), 128, 120)
  check("tank shot over open ground reaches the pill 7 away", ok, why)
  ok, why = S.tank_shot(env, c(128), c(127), c(128), c(120), 128, 120, { [sq(128, 125)] = 5 })
  check("tank shot through a planned wall: blocked", not ok and why == "planned", why)
  ok, why = S.tank_shot(env, c(128), c(128) + 100, c(128), c(120), 128, 120)
  check("tank shot from 8.4 squares: short", not ok and why == "short", why)
end

print(string.format("%d passed, %d failed", pass, fail))
if fail > 0 then os.exit(1) end
